import openpyxl,datetime as dt
from collections import Counter
wb=openpyxl.load_workbook("/workspace/documents/i9-audit-summary.xlsx")
ws=wb["Full Employee Roster"]
rows=list(ws.iter_rows(values_only=True))
h=rows[0]
P=lambda s: dt.datetime.strptime(s,"%m/%d/%Y").date() if s and s[0].isdigit() else None
for r in rows[1:]:
  d=dict(zip(h,r)); flags=[]
  hd=P(d["Date of Hire"]); s2=P(d["Section 2 Completion Date"])
  if hd and s2 and s2!=hd: flags.append(f"S2 {s2} vs hire {hd}")
  if hd and hd<dt.date(2007,3,12): flags.append("hired before formation")
  if hd and hd<dt.date(2012,1,10) and d["Section 2 Completed By"]=="S. Bledsoe": flags.append("Bledsoe pre-tenure")
  v=d["I-9 Form Version Used"]
  if v=="10/21/2019" and hd and hd<dt.date(2019,10,21): flags.append("2019 form for earlier hire")
  if v=="11/14/2016" and hd and (hd<dt.date(2016,11,14) or hd>dt.date(2020,4,30)): flags.append("2016 form anomaly")
  if d["Section 1 Completed By"] not in ("Employee",None,"N/A"): flags.append("S1 by "+str(d["Section 1 Completed By"]))
  if d["Section 3 Reverification Required (Yes/No)"]=="Yes": flags.append("S3")
  if d["Preparer/Translator Used (Yes/No)"]=="Yes": flags.append("prep")
  att=d["Section 1 Citizenship/Immigration Status Attestation"]
  if att not in ("U.S. Citizen",): flags.append("att="+str(att))
  if flags: print(d["Employee ID"],d["First Name"],d["Last Name"],d["Employment Status (Active/Terminated)"],"|",d["List A Document Type"],d["List A Expiration Date"],"|",flags)
print(Counter(r[14] for r in rows[1:]))
print(Counter(r[8] for r in rows[1:]))
EOF
